SELECT id, user_id, title, tech_direction, error_type, error_msg, is_favorite, is_top, review_count, create_time, update_time, deleted FROM mistake WHERE deleted = 1 AND user_id = #{userId}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR error_msg LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY update_time DESC
